 reset(enabled){this.enabled=enabled;this.time=0;this.scale=this.config.dilation.enabled?THREE.MathUtils.clamp(this.config.dilation.scale,this.config.dilation.minimum,this.config.dilation.maximum):1;this.boss.reset(Number(this.seedInput.value));this.boss.root.position.fromArray(this.config.arena.testingPosition);this.boss.model.sync();this.boss.sync();this.boss.root.visible=enabled;this.boss.effects.group.visible=enabled;for(const m of[this.boss.projectiles.mesh,this.boss.projectiles.outline,this.boss.projectiles.halo,this.boss.projectiles.debugMesh])m.visible=enabled;
  if(!enabled){this.boss.combatUnit.alive=false;this.boss.combatUnit.health=0;this.boss.combatUnit.shapes=[];}this.setDebug(enabled&&this.config.debug.enabled);if(!this.mission)document.querySelector('.viewer').classList.toggle('has-bastion',enabled);this.slowLabel();this.hud();}
 get sections(){return this.enabled?this.boss.sections:[];}
 player(){const heroes=this.getHeroes();this.hero=heroes.find(h=>h.active&&h.enabled!==false)||heroes.find(h=>h.enabled!==false);const h=this.hero,motion=h?.motion?.body||h?.motion;return{entity:h,position:h?.root.position.clone()||new THREE.Vector3(0,.08,30),motion:motion?.normal?motion:{mode:'air',normal:{x:0,y:1,z:0},velocity:h?.velocity||null},phased:!!h?.dash?.active||!!h?.motion?.dash};}
 hitHero(point,power,impact){const h=this.hero;if(!h||h.isDamageProtected?.())return;h.receiveEyeHit?.(point,power);if(impact?.kind!=='pulse')return;const c=impact.knockback,m=h.motion?.body||h.motion,away=h.root.position.clone().sub(impact.origin).setY(0);if(away.lengthSq()<1e-6)away.set(Math.sin(this.boss.root.rotation.y),0,Math.cos(this.boss.root.rotation.y));away.normalize().multiplyScalar(c.horizontalSpeed);away.y=c.upwardSpeed;m?.applyKnockback?.(away,c);this.boss.model.anchor=null;}
 update(dt){if(!this.enabled)return;const p=this.player();this.previous=p.position.clone();const worldDt=dt*this.scale;this.time+=worldDt;this.boss.worldSpeedScale=this.scale;this.boss.updateWorld(worldDt,this.time,p);if(this.hero?.motion?.support?.building==='bastion'){const yaw=this.boss.model.carry(this.hero.motion)||0;this.hero.yaw+=yaw;if(this.hero.heading)this.hero.heading.moveYaw+=yaw;}}
 afterHeroes(dt){if(!this.enabled)return;const p=this.player();this.boss.afterPlayer(dt,p,this.previous||p.position);this.hud();}
 attachCamera(hero){const original=hero.updateCamera.bind(hero);hero.updateCamera=(...args)=>{original(...args);if(!this.enabled||!hero.active)return;const camera=hero.camera;for(let i=0;i<this.config.arena.cameraResolveIterations;i++){let moved=false;for(const part of this.boss.model.parts){const s=part.section;if(s.hidden)continue;const q=s.body.quaternion.clone(),local=camera.position.clone().sub(s.body.position).applyQuaternion(q.clone().invert()),half=s.size.map(v=>v/2+this.config.arena.cameraClearance);if(Math.abs(local.x)>=half[0]||Math.abs(local.y)>=half[1]||Math.abs(local.z)>=half[2])continue;const distances=[half[0]-Math.abs(local.x),half[1]-Math.abs(local.y),half[2]-Math.abs(local.z)],axis=distances.indexOf(Math.min(...distances)),key=['x','y','z'][axis];local[key]=(Math.sign(local[key])||1)*half[axis];camera.position.copy(local.applyQuaternion(q).add(s.body.position));moved=true;}if(!moved)break;}camera.lookAt(camera.position.clone().addScaledVector(hero.aimDirection(),30));};}
 windupSound(){const hero=this.getHeroes().find(h=>h.feedback?.audio),audio=hero?.feedback.audio,c=this.config.audio;if(!c.enabled||!hero?.preferences.sound||audio?.state!=='running')return;const oscillator=audio.createOscillator(),gain=audio.createGain(),duration=this.config.timings.windup/this.scale;oscillator.frequency.setValueAtTime(c.startHz,audio.currentTime);oscillator.frequency.exponentialRampToValueAtTime(c.endHz,audio.currentTime+duration);gain.gain.setValueAtTime(c.gain,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);oscillator.connect(gain);gain.connect(audio.destination);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();};oscillator.start();oscillator.stop(audio.currentTime+duration+.02);}
 hud(){if(!this.enabled)return;const d=this.boss.diagnostics(),set=(selector,text)=>this.panel.querySelector(selector).textContent=text;
  set('[data-phase]',d.phase.toUpperCase()+' · '+(Number.isFinite(d.remaining)?d.remaining.toFixed(1)+'s':''));set('[data-core]','ARM CORES · '+d.armHealth.map((hp,i)=>(i?'R ':'L ')+Math.ceil(hp)).join(' / ')+' · BACK REACTOR ALWAYS EXPOSED');set('[data-pattern]','CYCLE '+d.cycle+' · '+(d.patterns.map(p=>p==='skyfall'?'PLASMA RAIN':'PLASMA GATLING').join(' + ')||'GATLING COOLING')+' · '+d.launchers.filter(l=>!l.destroyed).length+' weapon modules');set('[data-rain]',d.rain.active?'INCOMING · '+d.rain.active+' RED IMPACT ZONES':'');set('[data-graze]','NEXT STRIKE +'+Math.round(d.grazeBonus*100)+'% · HITS TAKEN '+d.hitsTaken);set('[data-route]','MARKED ROUTE · '+(d.markedRoute||'none'));
  if(this.debug)this.panel.querySelector('pre').textContent=JSON.stringify({phase:d.phase,cycle:d.cycle,patterns:d.patterns,route:d.currentRoute,marked:d.markedRoute,usage:d.routeSeconds,orbs:d.projectiles,worldScale:this.scale},null,2);
  const percent=Math.max(0,Math.ceil(d.health/d.maxHealth*100));document.querySelector('.boss-health-hud b').textContent='THE BASTION';document.getElementById('robot-percent').textContent=percent+'%';document.getElementById('robot-health').style.width=percent+'%';document.getElementById('boss-hp-meter').setAttribute('aria-valuenow',percent);
 }
